var n=`0817-kapana`;var a=`world-0817`;var t=`NA`;var s=`southern-africa`;var o=4;var r=48;var g={en:`Kapana`,ua:`Капана`};var l={en:`Kapana is a Namibia dish made with beef steak, yellow onion, tomato, lemon. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Капана, страва кухні країни Намібія. Основні складники: яловичий стейк, жовта цибуля, помідор, лимон. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 25 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 25 хвилин.`,t:[`marinating`],m:25,i:[[`beef-steak`,750,`g`],[`ground-coriander`,5,`g`],[`black-peppercorn`,4,`g`],[`table-salt`,null,`to_taste`]]},{en:`Grill over medium-high heat for about 15 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 15 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:15,i:[[`canola-oil`,35,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 6 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 6 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:6,i:[[`yellow-onion`,170,`g`],[`tomato`,200,`g`],[`cayenne-pepper-powder`,2,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`lemon`,1,`pcs`]]}];var u={slug:n,id:a,country:`NA`,region:s,servings:4,minutes:48,title:g,text:l,steps:d};export{t as country,u as default,a as id,r as minutes,s as region,o as servings,n as slug,d as steps,l as text,g as title};